// Waterfall Chart — Comparison, route: jsx
// Source: original:gaps/waterfall
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from waterfall ----
// Operating cash bridge for one fiscal year, in $M. Only the deltas are stored —
// a user's table carries only the deltas, so the chart derives the running total
// and the final Total bar itself.
const cashBridge: { name: string; delta: number }[] = [
  { name: 'Revenue', delta: 840 },
  { name: 'COGS', delta: -370 },
  { name: 'Marketing', delta: -140 },
  { name: 'R&D', delta: -95 },
  { name: 'G&A', delta: -70 },
  { name: 'Other income', delta: 25 },
  { name: 'Interest', delta: -15 },
  { name: 'Tax', delta: -45 }
];

const MARGIN = { top: 20, right: 12, bottom: 58, left: 48 };

const format = d3.format(',');
const signed = d3.format('+,');

/**
 * Named deltas in presentation order. The chart derives the running total, so
 * a bar floats from the previous cumulative value to the next, and a final
 * Total bar is appended automatically.
 */
export type Data = { name: string; delta: number }[];

type Bar = { name: string; y0: number; y1: number; kind: 'gain' | 'loss' | 'total' };

export default function WaterfallChart({ data = cashBridge, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const bars: Bar[] = useMemo(() => {
    let running = 0;
    const steps = data.map((d): Bar => {
      const y0 = running;
      running += d.delta;
      return { name: d.name, y0, y1: running, kind: d.delta >= 0 ? 'gain' : 'loss' };
    });
    return [...steps, { name: 'Total', y0: 0, y1: running, kind: 'total' }];
  }, [data]);

  const x = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(bars.map((b) => b.name))
        .range([0, Math.max(innerWidth, 0)])
        .padding(0.3),
    [bars, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([
          Math.min(0, d3.min(bars, (b) => Math.min(b.y0, b.y1)) ?? 0),
          d3.max(bars, (b) => Math.max(b.y0, b.y1)) ?? 1
        ])
        .nice()
        .range([Math.max(innerHeight, 0), 0]),
    [bars, innerHeight]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: format(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Waterfall chart of a yearly cash bridge: eight signed deltas step a running total from zero to the year-end result, with a derived final Total bar"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        {bars.map((b) => (
          // Rotated so adjacent category names cannot collide at any width.
          <text
            key={`label-${b.name}`}
            transform={`translate(${(x(b.name) ?? 0) + x.bandwidth() / 2},${innerHeight + 10}) rotate(-32)`}
            textAnchor="end"
            fontSize={10}
            fill="var(--text)"
          >
            {b.name}
          </text>
        ))}
        {bars.slice(0, -1).map((b, i) => (
          // Connector from each bar's end level to the start of the next bar.
          <line
            key={`connector-${b.name}`}
            x1={(x(b.name) ?? 0) + x.bandwidth()}
            x2={x(bars[i + 1].name) ?? 0}
            y1={y(b.y1)}
            y2={y(b.y1)}
            stroke="var(--muted)"
            strokeDasharray="2,2"
          />
        ))}
        {bars.map((b) => {
          const top = y(Math.max(b.y0, b.y1));
          const barHeight = Math.max(1, Math.abs(y(b.y0) - y(b.y1)));
          return (
            <g key={b.name}>
              <rect
                x={x(b.name)}
                y={top}
                width={x.bandwidth()}
                height={barHeight}
                fill={b.kind === 'loss' ? 'var(--muted)' : b.kind === 'gain' ? 'var(--accent)' : 'var(--text)'}
                fillOpacity={b.kind === 'total' ? 0.8 : 1}
                stroke={b.kind === 'loss' ? 'var(--text)' : 'none'}
              />
              <text
                x={(x(b.name) ?? 0) + x.bandwidth() / 2}
                y={top - 5}
                textAnchor="middle"
                fontSize={10}
                fill="var(--text)"
              >
                {b.kind === 'total' ? format(b.y1) : signed(b.y1 - b.y0)}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
